I have written in Java a simple, specialized HTTP server. It pre-generates an HTML page, serves it to any HTTP client on localhost that knows the randomly generated URL, then exits after 30 seconds.

(In the real application, the page is populated with actual content, but I've replaced it with random data for the sake of this example.)

This works fine if the HTML page is reasonably small, but if it grows to multiple megabytes, then attempting to fetch it with a browser, curl, or netcat will fail. Several hundred kilobytes are received (the exact byte count varies each time), then the connection drops with ECONNRESET before it finishes.

Any idea why ECONNRESET is happening?

The server is intended to serve requests from localhost only.

This happens on both Linux and Windows, so it seems unlikely that a firewall or other security software is responsible.

Here's the code:

```java
import java.io.IOException;
import java.io.InterruptedIOException;
import java.net.*;
import java.nio.ByteBuffer;
import java.nio.channels.ClosedByInterruptException;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.nio.charset.StandardCharsets;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.util.*;

class SimpleHttpServer {
	static void main() throws Throwable {
		// The real application sends real data, but we'll just send some random base64'd bytes as an example.
		byte[] randomBytes = new byte[5000000];
		new Random().nextBytes(randomBytes);
		byte[] randomBytesBase64 = Base64.getEncoder().encode(randomBytes);

		byte[] conclusion = "</p>\r\n\r\n<p>That's all, folks!</p></body></html>\r\n".getBytes(StandardCharsets.UTF_8);

		byte[] responseBytes = new byte[randomBytesBase64.length + conclusion.length];
		System.arraycopy(randomBytesBase64, 0, responseBytes, 0, randomBytesBase64.length);
		System.arraycopy(conclusion, 0, responseBytes, randomBytesBase64.length, conclusion.length);

		var server = SimpleHttpServer.start(responseBytes);
		System.err.println("Send requests to: " + server.getListenUri());
		server.listenThread.join();
	}

	private SimpleHttpServer(
		byte[] responseBytes,
		InetAddress listenAddress,
		int listenPort
	) {
		this.responseBytes = responseBytes;
		this.listenAddress = listenAddress;
		this.listenPort = listenPort;
		this.timer = new Timer("timer thread", true);

		try {
			var rng = SecureRandom.getInstanceStrong();
			var key = new byte[KEY_LEN];
			rng.nextBytes(key);

			expectedRequestPath = '/' + HexFormat.of().formatHex(key);
		}
		catch (NoSuchAlgorithmException e) {
			throw new Error(e);
		}

		expectedRequest =
			("GET " + expectedRequestPath + " HTTP/1.")
			.getBytes(StandardCharsets.US_ASCII);
	}

	static SimpleHttpServer start(
		byte[] responseBytes
	) throws IOException {
		InetAddress listenAddress = InetAddress.getLoopbackAddress();
		SimpleHttpServer server;
		var socket = ServerSocketChannel.open();

		try {
			socket.bind(new InetSocketAddress(listenAddress, 0));
			int listenPort = ((InetSocketAddress) socket.getLocalAddress()).getPort();

			server = new SimpleHttpServer(responseBytes, listenAddress, listenPort);

			server.listenThread =
				Thread.ofVirtual()
				.name("listener thread")
				.start(() -> server.acceptThread(socket));
		}
		catch (Throwable e) {
			try {
				socket.close();
			}
			catch (Throwable e2) {
				e.addSuppressed(e2);
			}

			throw e;
		}

		return server;
	}

	URI getListenUri() {
		String listenAddress =
			(this.listenAddress instanceof Inet6Address) ?
			('[' + this.listenAddress.getHostAddress() + ']') :
			this.listenAddress.getHostAddress();

		try {
			return new URI(
				"http",
				null,
				listenAddress,
				listenPort,
				expectedRequestPath,
				null,
				null
			);
		}
		catch (URISyntaxException e) {
			throw new Error(e);
		}
	}

	private void acceptThread(ServerSocketChannel socket) {
		try (socket) {
			scheduleInterruptThisThread();

			while (true) {
				SocketChannel connected = socket.accept();

				try {
					Thread.ofVirtual()
					.name("connected thread")
					.start(() -> serveThread(connected));
				}
				catch (Throwable e) {
					try {
						connected.close();
					}
					catch (Throwable e2) {
						e.addSuppressed(e2);
					}

					throw e;
				}
			}
		}
		catch (ClosedByInterruptException _) {}
		catch (Throwable e) {
			e.printStackTrace();
		}
	}

	private void serveThread(SocketChannel socket) {
		try (socket) {
			scheduleInterruptThisThread();

			// Read up to `expectedRequest.length` bytes from the request, or up to the first line feed, whichever comes first.
			var buf = ByteBuffer.allocate(expectedRequest.length);
			do {
				int bytesRead = socket.read(buf);
				if (bytesRead == -1)
					return;
			} while (buf.hasRemaining() && !byteBufferHasLineBreak(buf));
			buf.rewind();

			// If the request line exactly matches what we expect, then send our SUCCESS_RESPONSE and responseBytes. Otherwise, send a 404 error.
			if (ByteBuffer.wrap(expectedRequest).equals(buf)) {
				socket.write(ByteBuffer.wrap(SUCCESS_RESPONSE));
				socket.write(ByteBuffer.wrap(responseBytes));
			}
			else {
				socket.write(ByteBuffer.wrap(FAILURE_RESPONSE));
			}

			socket.shutdownOutput();
		}
		catch (Throwable e) {
			e.printStackTrace();
		}
	}

	private void scheduleInterruptThisThread() {
		final Thread thisThread = Thread.currentThread();

		timer.schedule(new TimerTask() {
			@Override
			public void run() {
				thisThread.interrupt();
			}
		}, THREAD_TIMEOUT_MILLISECONDS);
	}

	private static boolean byteBufferHasLineBreak(ByteBuffer buf) {
		for (int index = 0, length = buf.limit(); index < length; index++) {
			if (switch (buf.get(index)) {
				case 10, 13 -> true;
				default -> false;
			}) {
				return true;
			}
		}

		return false;
	}

	private final InetAddress listenAddress;
	private final int listenPort;
	private final byte[] responseBytes, expectedRequest;
	private final String expectedRequestPath;
	private final Timer timer;
	public Thread listenThread;

	private static final int
		THREAD_TIMEOUT_MILLISECONDS = 30000,
		KEY_LEN = 32;

	private static final byte[] SUCCESS_RESPONSE, FAILURE_RESPONSE;
	static {
		SUCCESS_RESPONSE = "HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=UTF-8\r\nServer: SimpleHttpServer\r\nConnection: close\r\nCache-Control: no-store\r\n\r\n<html><body><h1>Test Page</h1><p>".getBytes(StandardCharsets.UTF_8);

		FAILURE_RESPONSE = "HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nServer: SimpleHttpServer\r\nConnection: close\r\nCache-Control: no-store\r\n\r\n".getBytes(StandardCharsets.UTF_8);
	}
}
```

Any tips would be much appreciated.

